    def __init__(self):
        self.prefix = "default"
        self.version = 1

    def generate_key(self, identifier):
        return f"{self.prefix}_{self.version}_{identifier}"

    def clear_cache(self):
        print("Cache cleared")

    def list_keys(self): return []

def create_cache_key(data):
    """Generates a unique cache key."""
    return f"cache_{hash(data)}"


def validate_key(key):
    """Checks if the key is valid."""
    if not key:
        return False
    return key.startswith("cache_")


def purge_all():
    """Clears all cache entries."""
